#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    char kthCharacter(string s, long long k) {
        long long pos = 0, repeat = 0;
        for (char c : s) {
            if (c == ' ') {
                if (k == pos) return ' ';
                ++pos; repeat = 0;
            } else {
                ++repeat;
                if (k < pos + repeat) return c;
                pos += repeat;
            }
        }
        return ' ';
    }
};
